  ('19b6263c-311a-50a0-b4bf-c964ad6a6fe5', null, (select id from public.skills where slug = 'read-g9-figurative-language'), null, 'medium',
   $q$Dad announces that the family is taking "the scenic route." Based on the passage, what is this phrase really covering up?$q$, $q$[{"text":"That the highway was closed and the family had no other road.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"That Dad planned the longer drive to show his family the cornfields.","is_correct":false,"misconception_token":"literal-reading"},{"text":"That Mom chose the road because she knew a shortcut.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"That Dad missed the exit and did not want to admit the mistake.","is_correct":true}]$q$::jsonb, $q$That Dad missed the exit and did not want to admit the mistake.$q$, $q$The phrase comes right after Dad "missed the exit" and chose not to turn around, so it is a euphemism that makes a mistake sound like a choice. Mom's raised eyebrow shows she knows it was not a plan.$q$, 'draft', 'b529d6f7-7092-5e3d-9d11-a9c17f8c195f')
